draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Napoleon crowning
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // crown
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 - 20, H/2 - 40);
  ctx.lineTo(W/2 + 20, H/2 - 40);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // scepter
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 80);
  ctx.stroke();

  // rotating scepter
  ctx.save();
  ctx.translate(W/2, H/2 + 50);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(30, 0);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
